<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {Delete,Plus} from '@element-plus/icons-vue'
import {can,projectId} from '@/core/session'
import {onIdentityChange} from '@/core/http'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import {automationMixedTrigger,automationMixedPresentation,type AutomationDatetimeOptions} from './automation-mixed-triggers'
const props=defineProps<{value?:AutomationDatetimeOptions;enabled?:boolean;disabled?:boolean}>(),emit=defineEmits<{save:[value:AutomationDatetimeOptions,enabled:boolean];cancel:[]}>()
function nextHour(){const d=new Date();d.setMinutes(0,0,0);d.setHours(d.getHours()+1);const pad=(v:number)=>String(v).padStart(2,'0');return `${String(d.getFullYear()).padStart(4,'0')}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:00`}
const datetimes=ref([...(props.value?.datetimes??[nextHour()])]),presentation=automationMixedPresentation('DATETIME')
const enabled=ref(props.enabled??true),error=ref(''),permitted=computed(()=>can('rule:manage')&&!!projectId.value),blocked=computed(()=>props.disabled||!permitted.value)
function cancel(){if(!props.disabled)emit('cancel')}
watch([projectId,permitted],()=>emit('cancel'));const dispose=onIdentityChange(()=>emit('cancel'));onScopeDispose(dispose)
function save(){if(blocked.value)return;const row=automationMixedTrigger({kind:'DATETIME',enabled:enabled.value,options:{datetimes:datetimes.value}});if(!row||row.kind!=='DATETIME'){error.value='请填写有效的日期时间';return}emit('save',row.options,enabled.value)}
</script>
<template><el-dialog :model-value="true" title="配置触发项" width="800px" :lock-scroll="false" :close-on-click-modal="false" :close-on-press-escape="!disabled" :show-close="!disabled" append-to-body @update:model-value="cancel">
<div class="automation-time-type"><span :style="{background:presentation.background,color:presentation.color}"><ReferenceIcon :glyph="presentation.glyph"/></span><div><strong>{{presentation.label}}</strong><p>{{presentation.description}}</p></div></div><el-form label-position="top" size="small" :disabled="blocked"><el-form-item label="启用触发器"><el-switch v-model="enabled" aria-label="启用日期时间触发器" :disabled="blocked"/></el-form-item><el-form-item label="日期时间"><div class="automation-trigger-times"><div v-for="(_date,index) in datetimes" :key="index" class="automation-trigger-time"><el-date-picker v-model="datetimes[index]" type="datetime" format="YYYY-MM-DD HH:mm" value-format="YYYY-MM-DD HH:mm" placeholder="选择日期时间" size="small" :clearable="false" :aria-label="`日期时间 ${index+1}`" :disabled="blocked"/><el-button v-if="datetimes.length>1" :icon="Delete" text size="small" class="automation-trigger-delete" :aria-label="`删除日期时间 ${index+1}`" :disabled="blocked" @click="datetimes.splice(index,1)"/></div><el-button :icon="Plus" size="small" class="automation-trigger-add" :disabled="blocked||datetimes.length>=32" @click="datetimes.push(nextHour())">添加日期时间</el-button></div></el-form-item></el-form><el-alert v-if="error" :title="error" type="warning" :closable="false"/><template #footer><el-button :disabled="disabled" @click="cancel">取消</el-button><el-button type="primary" :disabled="blocked" @click="save">确定</el-button></template></el-dialog></template>
<style scoped>.automation-time-type{display:flex;align-items:center;gap:14px;padding:14px 16px;background:#f8f9fa;border-radius:8px;margin-bottom:20px}.automation-time-type>span{display:flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:10px;flex:none;font-size:22px}.automation-time-type strong{font-size:15px;font-weight:600;color:#333}.automation-time-type p{font-size:13px;color:#888;margin:4px 0 0}.automation-trigger-times{display:flex;flex-direction:column;gap:8px}.automation-trigger-time{display:flex;align-items:center;gap:8px}.automation-trigger-delete{color:#f56c6c;padding:8px}.automation-trigger-delete:hover{opacity:.8}.automation-trigger-add{margin-top:8px}.month-days-select{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:8px}.month-days-select :deep(.el-checkbox){margin:0;justify-self:start}</style>
